// ── Utilities ──────────────────────────────────────────────────────────────

function $(selector) { return document.querySelector(selector); }

function showError(inputEl, errorEl, message) {
  errorEl.textContent = message;
  errorEl.classList.add('visible');
  inputEl.setAttribute('aria-invalid', 'true');
}

function clearError(inputEl, errorEl) {
  errorEl.textContent = '';
  errorEl.classList.remove('visible');
  inputEl.removeAttribute('aria-invalid');
}

// ── Validators ─────────────────────────────────────────────────────────────

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
// Accepts international formats, optional country code, spaces/dashes/dots/parens
const PHONE_RE = /^[\+]?[(]?[0-9]{1,4}[)]?[-\s.]?[(]?[0-9]{1,4}[)]?[-\s.]?[0-9]{4,10}$/;

function validateFullName(value) {
  if (!value.trim()) return 'Error: Full name is required.';
  if (value.trim().length < 2) return 'Error: Enter your full name (at least 2 characters).';
  return null;
}

function validateEmail(value) {
  if (!value.trim()) return 'Error: Email address is required.';
  if (!EMAIL_RE.test(value.trim())) return 'Error: Enter a valid email address like name@example.com.';
  return null;
}

function validatePhone(value) {
  if (!value.trim()) return null; // optional
  if (!PHONE_RE.test(value.trim())) return 'Error: Enter a valid phone number, e.g. +1 555-123-4567.';
  return null;
}

// ── Field configuration ────────────────────────────────────────────────────

const FIELDS = [
  { inputId: 'full-name',  errorId: 'full-name-error',  validate: validateFullName },
  { inputId: 'email',      errorId: 'email-error',      validate: validateEmail    },
  { inputId: 'phone',      errorId: 'phone-error',      validate: validatePhone    },
];

// ── Inline (on-blur) validation ────────────────────────────────────────────

FIELDS.forEach(({ inputId, errorId, validate }) => {
  const input = document.getElementById(inputId);
  const error = document.getElementById(errorId);

  input.addEventListener('blur', () => {
    const msg = validate(input.value);
    if (msg) showError(input, error, msg);
    else      clearError(input, error);
  });

  // Clear error as soon as the user corrects the field
  input.addEventListener('input', () => {
    if (input.getAttribute('aria-invalid') === 'true') {
      const msg = validate(input.value);
      if (!msg) clearError(input, error);
    }
  });
});

// ── Submit ─────────────────────────────────────────────────────────────────

const form        = document.getElementById('contact-form');
const alertRegion = document.getElementById('form-alert');
const statusRegion = document.getElementById('form-status');

form.addEventListener('submit', (e) => {
  e.preventDefault();

  // Clear any previous success
  statusRegion.textContent = '';
  statusRegion.innerHTML   = '';

  const errors = [];

  FIELDS.forEach(({ inputId, errorId, validate }) => {
    const input = document.getElementById(inputId);
    const error = document.getElementById(errorId);
    const msg   = validate(input.value);
    if (msg) {
      showError(input, error, msg);
      errors.push({ input, msg });
    } else {
      clearError(input, error);
    }
  });

  if (errors.length > 0) {
    // Announce error count via alert region (no focus move needed when
    // the individual field errors are already visible near the inputs).
    // Then move focus to the first invalid field so keyboard/AT users land there.
    alertRegion.textContent = `${errors.length} error${errors.length > 1 ? 's' : ''} found. Please correct the highlighted fields.`;
    errors[0].input.focus();
    return;
  }

  // Clear alert region on success
  alertRegion.textContent = '';

  // Simulate submission
  const successHTML =
    '<svg aria-hidden="true" width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg"><circle cx="10" cy="10" r="9" stroke="#2ecc71" stroke-width="1.5"/><path d="M6 10l3 3 5-5" stroke="#2ecc71" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"/></svg>' +
    '<span>Your message has been sent. We\u2019ll get back to you shortly.</span>';

  const banner = document.createElement('div');
  banner.className = 'success-banner';
  banner.innerHTML = successHTML;

  statusRegion.appendChild(banner);

  // Reset the form
  form.reset();
  FIELDS.forEach(({ inputId, errorId }) => {
    clearError(document.getElementById(inputId), document.getElementById(errorId));
  });
});
