const { chromium } = require('/tmp/node_modules/playwright');
const fs = require('fs');

(async () => {
  const html = fs.readFileSync('index.html', 'utf8');
  const css  = fs.readFileSync('styles.css', 'utf8');
  const js   = fs.readFileSync('form.js', 'utf8');

  const inlined = html
    .replace('<link rel="stylesheet" href="styles.css" />', `<style>${css}</style>`)
    .replace('<script src="form.js"></script>', `<script>${js}</script>`);

  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.setContent(inlined, { waitUntil: 'load' });
  await page.addScriptTag({ path: '/tmp/axe.min.js' });

  const result = await page.evaluate(async () => await window.axe.run());
  await browser.close();

  const wcag = result.violations.filter(v => !v.tags.includes('best-practice'));
  const bp   = result.violations.filter(v =>  v.tags.includes('best-practice'));

  console.log(JSON.stringify({
    wcag: wcag.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })),
    bp:   bp.map(v   => ({ id: v.id, targets: v.nodes.map(n => n.target) }))
  }, null, 2));

  process.exit(wcag.length ? 1 : 0);
})();
EOF
